      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE DOCTRINE</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">One sentence, maximal claim</text>\n                    <rect x=\"100\" y=\"210\" width=\"900\" height=\"220\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"290\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"25\">\"To realize one's Personal Legend</text>\n                    <text x=\"160\" y=\"340\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"25\">is a person's only real obligation.\"</text>\n                    <text x=\"940\" y=\"395\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"19\">— Melchizedek, King of Salem</text>\n                    <rect x=\"150\" y=\"490\" width=\"800\" height=\"210\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"548\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">SEMINAR QUESTION</text>\n                    <text x=\"550\" y=\"595\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">'Only real obligation' — what does this ethic</text>\n                    <text x=\"550\" y=\"630\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">leave out? Duty to others? Community? Care?</text>\n                    <text x=\"550\" y=\"672\" text-anchor=\"middle\" fill=\"#888\" font-size=\"17\">Keep this question alive until Lesson 10</text>\n                </svg>",
