      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE RESENTMENT TEST</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Working the lesson into life and reading</text>\n                    <rect x=\"150\" y=\"190\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"200\" y=\"245\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">1.</text>\n                    <text x=\"250\" y=\"245\" text-anchor=\"start\" fill=\"#fff\" font-size=\"19\">Map a real abandoned ambition onto the prophecy</text>\n                    <rect x=\"150\" y=\"340\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(236,72,153,0.12)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"200\" y=\"395\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">2.</text>\n                    <text x=\"250\" y=\"395\" text-anchor=\"start\" fill=\"#fff\" font-size=\"19\">Reverse the genders; reread Fatima's speech</text>\n                    <rect x=\"150\" y=\"490\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"200\" y=\"545\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">3.</text>\n                    <text x=\"250\" y=\"545\" text-anchor=\"start\" fill=\"#fff\" font-size=\"19\">Perform one non-possessive act this week</text>\n                    <rect x=\"150\" y=\"640\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"200\" y=\"695\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">4.</text>\n                    <text x=\"250\" y=\"695\" text-anchor=\"start\" fill=\"#fff\" font-size=\"19\">Journal: what do oasis and desert stand for?</text>\n                </svg>",
