      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Functions of the marvelous</text>\n                    <rect x=\"80\" y=\"200\" width=\"440\" height=\"240\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"300\" y=\"260\" text-anchor=\"middle\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"20\">MAGICAL REALISM</text>\n                    <text x=\"300\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"17\">Unexplained eruption</text>\n                    <text x=\"300\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"17\">interrupts meaning</text>\n                    <text x=\"300\" y=\"395\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\">wound</text>\n                    <rect x=\"580\" y=\"200\" width=\"440\" height=\"240\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"800\" y=\"260\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"20\">WISDOM TALE</text>\n                    <text x=\"800\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"17\">Doctrinal demonstration</text>\n                    <text x=\"800\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"17\">confirms meaning</text>\n                    <text x=\"800\" y=\"395\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\">proof</text>\n                    <rect x=\"200\" y=\"510\" width=\"700\" height=\"120\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"560\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">Geography doesn't decide the genre —</text>\n                    <text x=\"550\" y=\"598\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">function does</text>\n                </svg>",
      "caption": "Wound versus proof: the decisive genre test"
