      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE LAST VERDICT</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Spoken over the open chest of gold</text>\n                    <rect x=\"100\" y=\"210\" width=\"900\" height=\"230\" rx=\"20\" fill=\"rgba(255,215,0,0.08)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"290\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"24\">\"It's true; life really is generous</text>\n                    <text x=\"160\" y=\"340\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"24\">to those who pursue their Personal Legend.\"</text>\n                    <text x=\"940\" y=\"400\" text-anchor=\"end\" fill=\"#ffd700\" font-size=\"19\">— Santiago, at the sycamore</text>\n                    <rect x=\"150\" y=\"500\" width=\"800\" height=\"220\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"558\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">SEMINAR NOTE</text>\n                    <text x=\"550\" y=\"603\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">The hero confirms the doctrine over a chest of gold —</text>\n                    <text x=\"550\" y=\"638\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">a conclusion available only to winners.</text>\n                    <text x=\"550\" y=\"680\" text-anchor=\"middle\" fill=\"#888\" font-size=\"17\">Hold that thought: it is Lesson 10's opening problem</text>\n                </svg>",
