      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The shape of the reception</text>\n                    <rect x=\"80\" y=\"220\" width=\"440\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"300\" y=\"280\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">SALES CURVE</text>\n                    <text x=\"300\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Up and to the right</text>\n                    <text x=\"300\" y=\"370\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">for three decades</text>\n                    <rect x=\"580\" y=\"220\" width=\"440\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"800\" y=\"280\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">CRITICAL CURVE</text>\n                    <text x=\"800\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Flat scorn or silence</text>\n                    <text x=\"800\" y=\"370\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Bloom, the Academy protests</text>\n                    <rect x=\"200\" y=\"490\" width=\"700\" height=\"120\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"540\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">Two metrics that never met:</text>\n                    <text x=\"550\" y=\"578\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">equipment for living vs. verbal art</text>\n                </svg>",
